// Normalize Calendly webhook payload (invitee.created & invitee.canceled)
const body = $input.item.json.body || $input.item.json;
const event = body.event || 'invitee.created';
const payload = body.payload || body;
const scheduledEvent = payload.scheduled_event || {};

// Invitee identification
const clientName = payload.name || (payload.first_name ? `${payload.first_name} ${payload.last_name || ''}`.trim() : 'Valued Client');
const clientEmail = payload.email || 'N/A';

// Process questions & answers
const questions = payload.questions_and_answers || [];
let clientPhone = payload.text_reminder_number || 'N/A';
let requestedService = scheduledEvent.name || 'Private Atelier Nail Art Session';
let instagramHandle = 'Not provided';

for (const qa of questions) {
  const q = (qa.question || '').toLowerCase();
  const a = (qa.answer || '').trim();
  if (q.includes('phone') || q.includes('teléfono') || q.includes('whatsapp') || q.includes('celular')) {
    clientPhone = a || clientPhone;
  }
  if (q.includes('service') || q.includes('servicio') || q.includes('diseño') || q.includes('tier') || qa.position === 0) {
    if (a) requestedService = a;
  }
  if (q.includes('instagram') || q.includes('ig') || q.includes('redes') || q.includes('handle')) {
    if (a) instagramHandle = a.startsWith('@') ? a : `@${a}`;
  }
}

// Clean phone for WhatsApp links (digits only)
const cleanPhone = clientPhone.replace(/[^0-9]/g, '');

// Times and Timezones
const rawStartTime = scheduledEvent.start_time || payload.event_start_time || payload.start_time || new Date().toISOString();
const rawEndTime = scheduledEvent.end_time || payload.event_end_time || payload.end_time || null;
const timezone = payload.timezone || scheduledEvent.timezone || 'America/New_York';

// Format dates for display in NY Atelier timezone
const startDateObj = new Date(rawStartTime);
const formattedDate = startDateObj.toLocaleDateString('en-US', {
  timeZone: timezone,
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});
const formattedTime = startDateObj.toLocaleTimeString('en-US', {
  timeZone: timezone,
  hour: 'numeric',
  minute: '2-digit',
  hour12: true
});
const formattedDateTime = `${formattedDate} at ${formattedTime} (${timezone})`;

// Cancellation metadata
const cancellation = payload.cancellation || {};
const canceledBy = cancellation.canceled_by || clientName;
const cancelReason = cancellation.reason || 'No specific reason provided';

// Schedule 24h prior reminder (Wait node target)
const reminderMs = startDateObj.getTime() - (24 * 60 * 60 * 1000);
const nowMs = Date.now();
const isShortNotice = reminderMs <= nowMs;
const reminderWaitDate = isShortNotice 
  ? new Date(nowMs + 15000).toISOString()
  : new Date(reminderMs).toISOString();

return {
  json: {
    eventType: event,
    isCreated: event === 'invitee.created',
    isCanceled: event === 'invitee.canceled',
    clientName,
    clientEmail,
    clientPhone,
    clientPhoneClean: cleanPhone,
    instagramHandle,
    serviceName: requestedService,
    rawStartTime,
    rawEndTime,
    timezone,
    formattedDate,
    formattedTime,
    formattedDateTime,
    canceledBy,
    cancelReason,
    reminderWaitDate,
    isShortNotice,
    depositAmount: 35,
    studioAddress: 'Bay Ridge, Brooklyn, NY 11209 (Private Atelier)',
    studioPhone: '+1 (929) 625-7273',
    studioPhoneE164: '+19296257273',
    studioInstagram: '@iva_nailart_nyc',
    studioInstagramDmUrl: 'https://ig.me/m/iva_nailart_nyc',
    studioWhatsappUrl: 'https://wa.me/19296257273',
    toleranceMinutes: 15,
    cancellationHours: 24,
    studioRules: '15 min grace period; 24h advance notice for cancellations.'
  }
};

